export function installChengliTextV27(dialogues){
 for(const {id,before,after} of CHENGLI_REWRITE_V27){
  const actual=JSON.stringify(dialogues[id]);
  if(actual===JSON.stringify(after))continue;
  if(actual!==JSON.stringify(before))throw new Error('第八章对白基线不一致：'+id);
  dialogues[id]=after.map(row=>[...row]);
 }
}
